		CASE WHEN @SortOrder = 'descend' AND @SortField = 'actualArrival' THEN r.[ActualArrival] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'plannedMealQty' THEN r.[PlannedMealQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'plannedMealQty' THEN r.[PlannedMealQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveredMealQty' THEN r.[DeliveredMealQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveredMealQty' THEN r.[DeliveredMealQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shortageQty' THEN r.[ShortageQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shortageQty' THEN r.[ShortageQty] END DESC,
